import json
LOW=[2,2,0,0,0,0,0,0,0]; UP=[4]*9; DEGS=list(range(4,37)); HS=[1,2,3,4]
def parts():
 out=[]
 def rec(i,prev,a):
  if i==9: out.append(tuple(a)); return
  for x in range(min(prev,UP[i]),LOW[i]-1,-1): rec(i+1,x,a+[x])
 rec(0,4,[]); return out
P=parts(); by={d:sorted((x for x in P if sum(x)==d),reverse=True) for d in DEGS}
def hor(mu,la): return all(mu[i]>=la[i]>=(mu[i+1] if i<8 else 0) for i in range(9))
def eye(n): return [[int(i==j) for j in range(n)] for i in range(n)]
def mm(A,B):
 if not A:return []
 if not B:return [[] for _ in A]
 return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def det_bareiss(A):
 n=len(A)
 if n==0:return 1
 B=[r[:] for r in A]; sign=1; prev=1
 for k in range(n-1):
  if B[k][k]==0:
   z=next((i for i in range(k+1,n) if B[i][k]),None)
   if z is None:return 0
   B[k],B[z]=B[z],B[k]; sign=-sign
  p=B[k][k]
  for i in range(k+1,n):
   for j in range(k+1,n): B[i][j]=(B[i][j]*p-B[i][k]*B[k][j])//prev
  prev=p
  for i in range(k+1,n):B[i][k]=0
 return sign*B[-1][-1]
def smith(M,n):
 m=len(M); A=[r[:] for r in M]; U=eye(m); V=eye(n)
 def rs(i,j): A[i],A[j]=A[j],A[i]; U[i],U[j]=U[j],U[i]
 def cs(i,j):
  for X in (A,V):
   for r in X:r[i],r[j]=r[j],r[i]
 def ra(i,j,q):
  A[i]=[x+q*y for x,y in zip(A[i],A[j])]; U[i]=[x+q*y for x,y in zip(U[i],U[j])]
 def ca(i,j,q):
  for X in (A,V):
   for r in X:r[i]+=q*r[j]
 def rn(i): A[i]=[-x for x in A[i]]; U[i]=[-x for x in U[i]]
 k=0
 while k<m and k<n:
  z=next(((i,j) for i in range(k,m) for j in range(k,n) if A[i][j]),None)
  if z is None:break
  rs(k,z[0]); cs(k,z[1])
  while True:
   # Euclidean reduction until pivot divides its row and column
   reduced=False
   for i in range(k+1,m):
    if A[i][k]%A[k][k]:
     q=A[i][k]//A[k][k]; ra(i,k,-q); rs(i,k); reduced=True; break
    elif A[i][k]: ra(i,k,-(A[i][k]//A[k][k]))
   if reduced:continue
   for j in range(k+1,n):
    if A[k][j]%A[k][k]:
     q=A[k][j]//A[k][k]; ca(j,k,-q); cs(j,k); reduced=True; break
    elif A[k][j]: ca(j,k,-(A[k][j]//A[k][k]))
   if reduced:continue
   bad=next(((i,j) for i in range(k+1,m) for j in range(k+1,n) if A[i][j]%A[k][k]),None)
   if bad is None:break
   # inject a nondivisible entry into pivot row
   ra(k,bad[0],1)
  if A[k][k]<0:rn(k)
  k+=1
 return U,V,A
def diagonal_ok(D):
 m=len(D); n=len(D[0]) if m else 0; last=1; seenzero=False
 for i in range(m):
  for j in range(n):
   if i!=j and D[i][j]:return False
 for i in range(min(m,n)):
  x=D[i][i]
  if x<0:return False
  if x==0:seenzero=True
  elif seenzero or x%last:return False
  elif x:last=x
 return True
records=[]
for d in DEGS:
 cols=by[d]; rows=[]; labels=[]; zeros=[]
 for t in HS:
  for la in by.get(d-t,[]):
   r=[int(hor(mu,la)) for mu in cols]; lab=[t,list(la)]
   if any(r):rows.append(r); labels.append(lab)
   else:zeros.append(lab)
 U,V,D=smith(rows,len(cols)); UM=mm(U,rows); UMV=mm(UM,V)
 rank=sum(D[i][i]!=0 for i in range(min(len(rows),len(cols))))
 sd=[D[i][i] for i in range(rank)]
 records.append({'degree':d,'orderedBasis':[list(x) for x in cols],'rowLabels':labels,'zeroRowLabels':zeros,'M':rows,'matrixShape':[len(rows),len(cols)],'U':U,'V':V,'D':D,'DShape':[len(rows),len(cols)],'smithDiagonal':sd,'rank':rank,'quotientFreeRank':len(cols)-rank,'torsionInvariantFactors':[x for x in sd if x>1],'checks':{'UMVEqualsD':UMV==D,'diagonalAndDivisibility':diagonal_ok(D),'detU':det_bareiss(U),'detV':det_bareiss(V),'unimodularU':abs(det_bareiss(U))==1,'unimodularV':abs(det_bareiss(V))==1}})
assert all(r['checks']['UMVEqualsD'] and r['checks']['diagonalAndDivisibility'] and r['checks']['unimodularU'] and r['checks']['unimodularV'] for r in records)
print(json.dumps({'inputs':{'lower':LOW,'upper':UP,'degrees':DEGS,'hDegrees':HS,'columnOrder':'reverse lexicographic','rowOrder':'h-degree then source reverse lexicographic','pieriRule':'coefficient 1 iff mu_i >= lambda_i >= mu_(i+1), with mu_10=0'},'records':records},separators=(',',':')))
